import{escapeHtml}from"./domUtils.js";const RX_URL="^([a-zA-Z]+:\\/\\/)?((([a-z\\d]([a-z\\d-]*[a-z\\d])*)\\.)+[a-z]{2,}|((\\d{1,3}\\.){3}\\d{1,3}))(\\:\\d+)?(\\/[-a-z\\d%_.~+]*)*(\\?[;&a-z\\d%_.~+=-]*)?(\\#[-a-z\\d_]*)?",RX_EMAIL=/\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/g,attributesToStr=e=>Object.entries(e).reduce(((e,t)=>`${e} ${t[0]}"="${escapeHtml(t[1])}"`),"");export const urlify=(e,t)=>{let r='target="_blank" rel="nofollow noopener noreferrer"';"object"!=typeof t||Array.isArray(t)||null===t||(r=attributesToStr(t));const a=`<a ${r} href="$&">$&</a>`;return e.replaceAll(new RegExp(RX_URL,"gim"),a)};export const emailify=e=>e.replace(RX_EMAIL,(e=>`<a href="mailto:${e}">${e}</a>`));export const extractAnchors=(e,t)=>{const r=document.createElement("div");r.innerHTML=e;const a=r.getElementsByTagName("a"),o=new Set;for(const e of a)e.href&&o.add(t?e.href:e);return o};export const normalizeDiacritics=e=>e.normalize("NFD").replace(/[\u0300-\u036f]/g,"").normalize("NFC");export const nvl=(e,t)=>e||t||"";